/// Returns the nth Fibonacci number using the naive recursive definition.
///
/// `fibonacci(0) == 0`, `fibonacci(1) == 1`, and for `n >= 2`
/// `fibonacci(n) == fibonacci(n - 1) + fibonacci(n - 2)`.
///
/// This is an exponential-time implementation intended for illustration;
/// it is not suitable for large `n`.
pub fn fibonacci(n: u32) -> u64 {
    match n {
        0 => 0,
        1 => 1,
        _ => fibonacci(n - 1) + fibonacci(n - 2),
    }
}"}
